// src/services/contract-resolver.ts
var SOURCIFY_BASE_URL = "https://sourcify.dev/server/v2";
async function resolveContractAbi(input2) {
  const normalizedAddress = getAddress(input2.address);
  const protocolContract = findProtocolContract({
    chainId: input2.chainId,
    address: normalizedAddress
  });
  if (protocolContract) {
    return {
      found: true,
      contract: {
        address: normalizedAddress,
        chainId: input2.chainId,
        abi: protocolContract.abi,
        source: "protocol",
        verified: true,
        protocol: protocolContract.protocol
      }
    };
  }
  const url2 = `${SOURCIFY_BASE_URL}/contract/` + `${input2.chainId}/${normalizedAddress}` + `?fields=abi`;
  try {
    const response = await fetch(url2, {
      headers: {
        Accept: "application/json"
      }
    });
    if (response.status === 404) {
      return {
        found: false,
        error: "Contract ABI was not found in Sourcify."
      };
    }
    if (!response.ok) {
      return {
        found: false,
        error: `Sourcify returned HTTP ${response.status}.`
      };
    }
    const data = await response.json();
    if (!Array.isArray(data.abi)) {
      return {
        found: false,
        error: "Sourcify returned a contract without a valid ABI."
      };
    }
    return {
      found: true,
      contract: {
        address: normalizedAddress,
        chainId: input2.chainId,
        abi: data.abi,
        source: "sourcify",
        verified: data.match === "exact_match" || data.match === "match"
      }
    };
  } catch (error62) {
    return {
      found: false,
      error: error62 instanceof Error ? error62.message : "Unknown Sourcify error."
    };
  }
}

// src/lib/decoder.ts
function decodeWithAbi(abi2, data) {
  try {
    const decoded = decodeFunctionData({
      abi: abi2,
      data
    });
    return {
      functionName: decoded.functionName,
      args: decoded.args ?? []
    };
  } catch {
    return null;
  }
}
async function decodeTransactionData(input2) {
  const { chainId, to, data } = input2;
  if (data === "0x") {
    return {
      decoded: false,
      classification: {
        action: "UNKNOWN",
        riskLevel: "LOW",
        description: "Native BNB transfer with no contract calldata."
      },
      abiSource: "unknown",
      contractVerified: false
    };
  }
  const selector = data.slice(0, 10);
  const localDecoded = decodeWithAbi(securityAbi, data);
  if (localDecoded) {
    const protocolContract = findProtocolContract({
      chainId,
      address: to
    });
    const classification = classifyAction(localDecoded.functionName, localDecoded.args, protocolContract?.protocol);
    return {
      decoded: true,
      functionName: localDecoded.functionName,
      args: localDecoded.args,
      selector,
      classification,
      abiSource: "local",
      contractVerified: true,
      protocol: protocolContract?.protocol
    };
  }
  const resolved = await resolveContractAbi({
    chainId,
    address: to
  });
  if (resolved.found && resolved.contract) {
    const externalDecoded = decodeWithAbi(resolved.contract.abi, data);
    if (externalDecoded) {
      const classification = classifyAction(externalDecoded.functionName, externalDecoded.args, resolved.contract.protocol);
      return {
        decoded: true,
        functionName: externalDecoded.functionName,
        args: externalDecoded.args,
        selector,
        classification,
        abiSource: resolved.contract.source,
        contractVerified: resolved.contract.verified,
        protocol: resolved.contract.protocol
      };
    }
  }
  return {
    decoded: false,
    selector,
    classification: {
      action: "UNKNOWN",
      riskLevel: "MEDIUM",
      description: "Function selector is not recognized by the available ABI sources."
    },
    abiSource: resolved.found ? resolved.contract?.source ?? "unknown" : "unknown",
    protocol: resolved.contract?.protocol,
    contractVerified: resolved.contract?.verified ?? false
  };
}

// src/lib/serialize.ts
function serializeBigInt(value) {
  if (typeof value === "bigint") {
    return value.toString();
  }
  if (Array.isArray(value)) {
    return value.map(serializeBigInt);
  }
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, val]) => [key, serializeBigInt(val)]));
  }
  return value;
}

// src/services/simulator.ts
async function simulateTransaction(tx) {
  try {
    const result = await publicClient.call({
      account: tx.from,
      to: tx.to,
      value: tx.value,
      data: tx.data
    });
    let gasEstimate = null;
    try {
      gasEstimate = await publicClient.estimateGas({
        account: tx.from,
        to: tx.to,
        value: tx.value,
        data: tx.data
      });
    } catch {
      gasEstimate = null;
    }
    return {
      success: true,
      gasEstimate: gasEstimate?.toString() ?? null,
      returnData: result.data ?? null,
      error: null
    };
  } catch (error62) {
    return {
      success: false,
      gasEstimate: null,
      returnData: null,
      error: extractSimulationError(error62)
    };
  }
}
function extractSimulationError(error62) {
  if (error62 instanceof Error) {
    return error62.message;
  }
  return "Transaction simulation reverted.";
}

