// src/services/state-diff.ts
var MAX_UINT256 = 2n ** 256n - 1n;
async function analyzeStateDiff(input2) {
  const result = {
    approvals: []
  };
  if (input2.data === "0x") {
    return result;
  }
  const selector = input2.data.slice(0, 10);
  if (selector === "0x095ea7b3") {
    try {
      const spender = extractAddress(input2.data, 0);
      const amount = extractUint256(input2.data, 1);
      const before = await publicClient.readContract({
        address: input2.to,
        abi: securityAbi,
        functionName: "allowance",
        args: [
          input2.from,
          spender
        ]
      });
      result.approvals.push({
        type: "ERC20_ALLOWANCE",
        token: input2.to,
        owner: input2.from,
        spender,
        before,
        after: amount,
        unlimited: amount === MAX_UINT256,
        stateKnown: true
      });
      return result;
    } catch (error62) {
      console.error("ERC20 state diff failed:", error62);
      return result;
    }
  }
  if (selector === "0xa22cb465") {
    const operator = extractAddress(input2.data, 0);
    const approved = extractBool(input2.data, 1);
    const before = await getApprovalState(input2.to, input2.from, operator);
    if (before === null) {
      result.approvals.push({
        type: "ERC721_OPERATOR",
        token: input2.to,
        owner: input2.from,
        spender: operator,
        before: 0n,
        after: approved ? 1n : 0n,
        unlimited: approved,
        stateKnown: false
      });
      return result;
    }
    result.approvals.push({
      type: "ERC721_OPERATOR",
      token: input2.to,
      owner: input2.from,
      spender: operator,
      before: before ? 1n : 0n,
      after: approved ? 1n : 0n,
      unlimited: approved,
      stateKnown: true
    });
    return result;
  }
  return result;
}
function extractAddress(data, index2) {
  const start = 10 + index2 * 64;
  const word = data.slice(start, start + 64);
  return `0x${word.slice(24)}`;
}
function extractUint256(data, index2) {
  const start = 10 + index2 * 64;
  const word = data.slice(start, start + 64);
  return BigInt(`0x${word}`);
}
function extractBool(data, index2) {
  return extractUint256(data, index2) !== 0n;
}

