// src/services/effect-state.ts
async function resolveEffectState(effects) {
  const diffs = [];
  for (const approval of effects.approvals) {
    if (approval.type !== "ERC721_OPERATOR") {
      continue;
    }
    const before = await getApprovalState(approval.token, approval.owner, approval.operator);
    diffs.push({
      type: "ERC721_OPERATOR",
      token: approval.token,
      owner: approval.owner,
      operator: approval.operator,
      before,
      after: approval.approved,
      sourceFunction: approval.sourceFunction
    });
  }
  return diffs;
}

// src/services/risk-engine.ts
var RISK_RANK = {
  LOW: 0,
  MEDIUM: 1,
  HIGH: 2,
  CRITICAL: 3
};
function calculateRisk(effects, action, approvalEffects = []) {
  let score = 0;
  const reasons = [];
  if (action === "NFT_APPROVAL") {
    score = Math.max(score, 90);
    reasons.push("Transaction requests NFT operator approval.");
  }
  for (const approval of approvalEffects) {
    if (approval.type !== "ERC20_ALLOWANCE") {
      continue;
    }
    if (approval.unlimited) {
      score = Math.max(score, 90);
      reasons.push("Transaction requests an unlimited ERC20 token allowance.");
    } else {
      score = Math.max(score, 60);
      reasons.push("Transaction grants an ERC20 token allowance to another address.");
    }
  }
  for (const effect of effects) {
    if (effect.type !== "ERC721_OPERATOR") {
      continue;
    }
    if (effect.after === true) {
      score = Math.max(score, 90);
      if (effect.before === false) {
        reasons.push("NFT operator approval changes from disabled to enabled.");
      } else if (effect.before === null) {
        reasons.push("NFT operator approval is requested, but the previous approval state could not be verified.");
      } else {
        reasons.push("NFT operator approval is enabled.");
      }
    }
  }
  score = Math.min(score, 100);
  let level = "LOW";
  if (score >= 80) {
    level = "CRITICAL";
  } else if (score >= 60) {
    level = "HIGH";
  } else if (score >= 30) {
    level = "MEDIUM";
  }
  return {
    score,
    level,
    reasons
  };
}
function mergeScamRisk(risk, scamRisk) {
  if (!scamRisk)
    return risk;
  const level = RISK_RANK[risk.level] >= RISK_RANK[scamRisk.level] ? risk.level : scamRisk.level;
  return {
    score: Math.max(risk.score, scamRisk.score),
    level,
    reasons: [...new Set([...risk.reasons, ...scamRisk.reasons])]
  };
}

// src/services/intent-normalizer.ts
function normalizeIntent(intent) {
  let maxValueWei = null;
  if (intent.maxValueNative !== null) {
    if (intent.nativeCurrency !== "BNB") {
      throw new Error("Unsupported native currency.");
    }
    maxValueWei = parseEther2(intent.maxValueNative);
  }
  const tokenIn = intent.tokenIn ?? intent.inputAsset ?? null;
  const tokenOut = intent.tokenOut ?? intent.outputAsset ?? null;
  return {
    ...intent,
    tokenIn,
    tokenOut,
    inputAsset: intent.inputAsset ?? tokenIn,
    outputAsset: intent.outputAsset ?? tokenOut,
    maxValueWei
  };
}

