// src/services/security-decision.ts
function makeSecurityDecision(input2) {
  const reasons = new Set;
  if (!input2.simulationSuccess) {
    reasons.add("Transaction simulation reverted.");
    return {
      decision: "BLOCK",
      reasons: [...reasons]
    };
  }
  if (!input2.policy.allowed) {
    for (const reason of input2.policy.reasons) {
      reasons.add(reason);
    }
    return {
      decision: "BLOCK",
      reasons: [...reasons]
    };
  }
  const criticalScamAnalyses = input2.scamAnalyses?.filter((analysis) => analysis.riskLevel === "CRITICAL") ?? [];
  if (criticalScamAnalyses.length > 0) {
    for (const analysis of criticalScamAnalyses) {
      for (const finding of analysis.findings) {
        if (finding.severity === "CRITICAL") {
          reasons.add(`${analysis.token}: ${finding.title}`);
        }
      }
    }
    return {
      decision: "BLOCK",
      reasons: [...reasons]
    };
  }
  if (input2.risk.level === "CRITICAL") {
    for (const reason of input2.risk.reasons) {
      reasons.add(reason);
    }
    return {
      decision: "BLOCK",
      reasons: [...reasons]
    };
  }
  if (!input2.comparison.matches) {
    for (const mismatch of input2.comparison.mismatches) {
      reasons.add(mismatch);
    }
    if (input2.policy.requiresReview) {
      for (const reason of input2.policy.reasons) {
        reasons.add(reason);
      }
    }
    if (input2.risk.level === "HIGH") {
      return {
        decision: "BLOCK",
        reasons: [...reasons]
      };
    }
    return {
      decision: "REVIEW",
      reasons: [...reasons]
    };
  }
  if (input2.policy.requiresReview) {
    for (const reason of input2.policy.reasons) {
      reasons.add(reason);
    }
    return {
      decision: "REVIEW",
      reasons: [...reasons]
    };
  }
  if (input2.risk.level === "HIGH") {
    for (const reason of input2.risk.reasons) {
      reasons.add(reason);
    }
    return {
      decision: "REVIEW",
      reasons: [...reasons]
    };
  }
  return {
    decision: "ALLOW",
    reasons: []
  };
}

