  MINT: "MINT_CAPABILITY",
  PAUSE: "PAUSE_CAPABILITY",
  BLACKLIST: "BLACKLIST_CAPABILITY",
  TAX: "TAX_CAPABILITY",
  LIMITS: "LIMITS_CAPABILITY",
  TRADING: "TRADING_CAPABILITY",
  ROUTER: "ROUTER_CAPABILITY",
