// src/services/scam/scam-risk-engine.ts
var SEVERITY_WEIGHT = {
  INFO: 0,
  LOW: 15,
  MEDIUM: 35,
  HIGH: 65,
  CRITICAL: 95
};
var SEVERITY_CAP = {
  INFO: 0,
  LOW: 25,
  MEDIUM: 55,
  HIGH: 75,
  CRITICAL: 100
};
var SEVERITY_RANK = {
  INFO: 0,
  LOW: 1,
  MEDIUM: 2,
  HIGH: 3,
  CRITICAL: 4
};
function levelForScore(score) {
  if (score >= 80)
    return "CRITICAL";
  if (score >= 60)
    return "HIGH";
  if (score >= 30)
    return "MEDIUM";
  return "LOW";
}
function calculateScamRisk(findings) {
  const unique2 = [...new Map(findings.map((finding) => [`${finding.code}:${finding.evidence ?? finding.title}`, finding])).values()];
  let highest = "INFO";
  let score = 0;
  for (const finding of unique2) {
    score += SEVERITY_WEIGHT[finding.severity];
    if (SEVERITY_RANK[finding.severity] > SEVERITY_RANK[highest]) {
      highest = finding.severity;
    }
  }
  score = Math.min(score, SEVERITY_CAP[highest]);
  return {
    score,
    level: levelForScore(score),
    reasons: unique2.map((finding) => finding.title)
  };
}

