// src/services/scam/transaction-threat-analyzer.ts
function analyzeTransactionThreats(input2) {
  const findings = [];
  const functionName = input2.functionName?.toLowerCase() ?? "";
  for (const approval of input2.effects.approvals) {
    if (approval.type === "ERC20_ALLOWANCE") {
      if (approval.unlimited) {
        findings.push({
          code: "UNLIMITED_ALLOWANCE",
          severity: "HIGH",
          title: "Unlimited token spending permission",
          description: "The transaction grants another address permission to spend an unrestricted amount of this token.",
          evidence: `Spender: ${approval.spender}.`,
          source: "CONTRACT"
        });
      }
      if (!input2.intentAllowsApproval) {
        findings.push({
          code: "UNEXPECTED_SPENDER",
          severity: approval.unlimited ? "CRITICAL" : "HIGH",
          title: "Unexpected token spending permission",
          description: "The transaction grants token-spending permission even though the user's intent did not include an approval.",
          evidence: `Spender: ${approval.spender}. Amount: ${approval.amount.toString()}.`,
          source: "CONTRACT"
        });
      }
      if (input2.counterpartyContracts?.has(approval.spender.toLowerCase())) {
        findings.push({
          code: "APPROVAL_TO_CONTRACT",
          severity: approval.unlimited ? "HIGH" : "MEDIUM",
          title: "Token permission targets a contract",
          description: "The token spending permission is granted to another smart contract.",
          evidence: `Spender: ${approval.spender}.`,
          source: "ONCHAIN"
        });
      }
    }
    if (approval.type === "ERC721_OPERATOR" && approval.approved) {
      findings.push({
        code: input2.intentAllowsApproval ? "APPROVAL_TO_CONTRACT" : "UNEXPECTED_NFT_OPERATOR",
        severity: input2.intentAllowsApproval ? "HIGH" : "CRITICAL",
        title: input2.intentAllowsApproval ? "NFT operator permission granted" : "Unexpected NFT operator permission",
        description: input2.intentAllowsApproval ? "The transaction gives another address permission to manage NFTs from this collection." : "The transaction gives another address permission to manage NFTs even though the user's intent did not include an NFT approval.",
        evidence: `Operator: ${approval.operator}. Token contract: ${approval.token}.`,
        source: "CONTRACT"
      });
    }
  }
  if (input2.action === "TOKEN_TRANSFER_FROM") {
    findings.push({
      code: "THIRD_PARTY_TOKEN_TRANSFER",
      severity: "HIGH",
      title: "Third-party token transfer",
      description: "The transaction attempts to move tokens from an address through a transferFrom-style operation.",
      evidence: "transferFrom semantics were detected from the decoded transaction.",
      source: "CONTRACT"
    });
  }
  if (input2.targetIsContract === false && input2.functionName) {
    findings.push({
      code: "CONTRACT_TARGET_IS_EOA",
      severity: "HIGH",
      title: "Transaction target is not a smart contract",
      description: "The wallet request contains contract calldata, but the target address does not currently contain contract code.",
      evidence: `Target: ${input2.to}.`,
      source: "ONCHAIN"
    });
  }
  if (input2.action === "UNKNOWN" && input2.functionName === null) {
    findings.push({
      code: "UNIDENTIFIED_CONTRACT_CALL",
      severity: input2.contractVerified === false ? "HIGH" : "MEDIUM",
      title: "Transaction behavior could not be identified",
      description: "Nalar could not decode the contract call from the available ABI evidence.",
      evidence: input2.contractVerified === false ? "The target contract is not verified in the available ABI source." : "The transaction selector could not be matched to an available ABI.",
      source: "CONTRACT"
    });
  }
  if (functionName === "multicall" || functionName === "aggregate" || functionName === "aggregate3" || functionName === "tryaggregate") {
    findings.push({
      code: "SUSPICIOUS_MULTICALL",
      severity: "MEDIUM",
      title: "Batch contract execution detected",
      description: "The transaction can execute multiple contract calls through a single wallet request.",
      evidence: `Function: ${input2.functionName}.`,
      source: "CONTRACT"
    });
  }
  if (functionName === "delegatecall" || functionName === "executedelegatecall") {
    findings.push({
      code: "DELEGATECALL_TARGET",
      severity: input2.contractVerified === false ? "CRITICAL" : "HIGH",
      title: "Delegatecall execution detected",
      description: "The transaction can execute code in the context of the target contract, which requires careful inspection of the delegated target.",
      evidence: `Function: ${input2.functionName}. Target: ${input2.to}.`,
      source: "CONTRACT"
    });
  }
  const arbitraryCallFunctions = new Set(["functioncall", "functioncallwithvalue", "execute", "executebatch", "call", "callwithvalue"]);
  if (arbitraryCallFunctions.has(functionName) && input2.protocol !== "PancakeSwap") {
    findings.push({
      code: "ARBITRARY_EXTERNAL_CALL",
      severity: input2.contractVerified === false ? "HIGH" : "MEDIUM",
      title: "External contract execution detected",
      description: "The transaction invokes a generic execution function that may dispatch additional contract calls.",
      evidence: `Function: ${input2.functionName}. Target: ${input2.to}.`,
      source: "CONTRACT"
    });
  }
  if (input2.value > 0n && input2.contractVerified === false && input2.targetIsContract !== false) {
    findings.push({
      code: "NATIVE_VALUE_TO_UNVERIFIED_CONTRACT",
      severity: "MEDIUM",
      title: "Native BNB is sent to an unverified contract",
      description: "The transaction sends native BNB to a contract whose available source verification could not be established.",
      evidence: `Value: ${input2.value.toString()} wei. Target: ${input2.to}.`,
      source: "ONCHAIN"
    });
  }
  if (input2.action === "UNKNOWN" && input2.value > 0n) {
    findings.push({
      code: "UNKNOWN_EXECUTION_PATH",
      severity: "HIGH",
      title: "Execution path is not understood",
      description: "The transaction carries value but Nalar could not establish the semantic action performed by the target contract.",
      evidence: `Target: ${input2.to}. Value: ${input2.value.toString()} wei.`,
      source: "CONTRACT"
    });
  }
  return dedupeFindings(findings);
}
function dedupeFindings(findings) {
  return [...new Map(findings.map((finding) => [`${finding.code}:${finding.evidence ?? finding.title}`, finding])).values()];
}

// src/services/scam/bnb-transaction-investigator.ts
class BnbTransactionInvestigator {
  mcp;
  constructor(mcp) {
    this.mcp = mcp;
  }
  async investigate(input2) {
    const network = input2.chainId === 97 ? "bsc-testnet" : input2.chainId === 56 ? "bsc" : `chain-${input2.chainId}`;
    const observations = [];
    const contractAddresses = new Set;
    try {
      const targetResult = await this.mcp.isContract({
        address: input2.to,
        network
      });
      const targetValue = this.extractValue(targetResult);
      observations.push({
        type: "TARGET_CONTRACT",
        address: input2.to,
        value: targetValue,
        source: "BNB_MCP",
        evidence: `BNB MCP is_contract result for ${input2.to}: ${targetValue}`
      });
      if (this.looksLikeContract(targetValue)) {
        contractAddresses.add(input2.to.toLowerCase());
      }
      for (const approval of input2.effects.approvals) {
        const address = approval.type === "ERC20_ALLOWANCE" ? approval.spender : approval.operator;
        if (contractAddresses.has(address.toLowerCase())) {
          continue;
        }
        try {
          const result = await this.mcp.isContract({
            address,
            network
          });
          const value = this.extractValue(result);
          observations.push({
            type: "COUNTERPARTY_CONTRACT",
            address,
            value,
            source: "BNB_MCP",
            evidence: `BNB MCP is_contract result for ${address}: ${value}`
          });
          if (this.looksLikeContract(value)) {
            contractAddresses.add(address.toLowerCase());
          }
        } catch {}
      }
      try {
        const latestBlock = await this.mcp.getLatestBlock({
          network
        });
        observations.push({
          type: "LATEST_BLOCK",
          value: this.extractValue(latestBlock),
          source: "BNB_MCP",
          evidence: "Latest BNB block context retrieved through MCP."
        });
      } catch {}
      return {
        available: observations.length > 0,
        observations,
        contractAddresses: [...contractAddresses],
        summary: `BNB MCP investigation completed with ${observations.length} observations.`
      };
    } catch (error62) {
      return {
        available: false,
        observations,
        contractAddresses: [...contractAddresses],
        summary: error62 instanceof Error ? error62.message : "BNB MCP transaction investigation failed."
      };
    }
  }
  extractValue(value) {
    if (typeof value === "string") {
      return value;
    }
    if (typeof value === "boolean") {
      return String(value);
    }
    if (typeof value === "number") {
      return String(value);
    }
    if (typeof value === "bigint") {
      return value.toString();
    }
    if (Array.isArray(value)) {
      return value.length === 1 ? this.extractValue(value[0]) : JSON.stringify(value);
    }
    if (value && typeof value === "object") {
      const object2 = value;
      for (const key of ["value", "result", "output", "data"]) {
        if (key in object2) {
          return this.extractValue(object2[key]);
        }
      }
      if (Array.isArray(object2.content)) {
        return this.extractValue(object2.content);
      }
      try {
        return JSON.stringify(value);
      } catch {
        return "unavailable";
      }
    }
    return "unavailable";
  }
  looksLikeContract(value) {
    const normalized = value.toLowerCase();
    return normalized === "true" || normalized === "is_contract: true" || normalized.includes('"iscontract":true');
  }
}

